from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

n = 23
edges = []
edge_vars = {}
var_counter = 1

for i in range(n):
    for j in range(i + 1, n):
        edge_vars[(i, j)] = var_counter
        edge_vars[(j, i)] = var_counter
        edges.append((i, j))
        var_counter += 1

solver = Glucose4()

# Degree constraints
for i in range(n):
    incident_vars = [edge_vars[(i, j)] for j in range(n) if i != j]
    # Degree >= 3
    cnf_atleast = CardEnc.atleast(lits=incident_vars, bound=3, top_id=var_counter)
    for clause in cnf_atleast.clauses:
        solver.add_clause(clause)
    var_counter = max(var_counter, cnf_atleast.nv + 1) if cnf_atleast.clauses else var_counter

    # Degree <= 4
    cnf_atmost = CardEnc.atmost(lits=incident_vars, bound=4, top_id=var_counter)
    for clause in cnf_atmost.clauses:
        solver.add_clause(clause)
    var_counter = max(var_counter, cnf_atmost.nv + 1) if cnf_atmost.clauses else var_counter

# Girth >= 6 (no cycles of length 3, 4, 5)
# Length 3
for c in itertools.combinations(range(n), 3):
    solver.add_clause([-edge_vars[(c[0], c[1])], -edge_vars[(c[1], c[2])], -edge_vars[(c[0], c[2])]])

# Length 4
for c in itertools.combinations(range(n), 4):
    for p in itertools.permutations(c):
        # To avoid duplicates, we can just fix the first element and the direction
        if p[0] < p[1] and p[0] < p[2] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-edge_vars[(p[0], p[1])], -edge_vars[(p[1], p[2])], -edge_vars[(p[2], p[3])], -edge_vars[(p[3], p[0])]])

# Length 5
for c in itertools.combinations(range(n), 5):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-edge_vars[(p[0], p[1])], -edge_vars[(p[1], p[2])], -edge_vars[(p[2], p[3])], -edge_vars[(p[3], p[4])], -edge_vars[(p[4], p[0])]])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    result_edges = []
    for i, j in edges:
        if model[edge_vars[(i, j)] - 1] > 0:
            result_edges.append((i, j))
    print(result_edges)
else:
    print("UNSAT")

import networkx as nx

edges = [(0, 9), (0, 13), (0, 21), (1, 12), (1, 13), (1, 20), (2, 10), (2, 16), (2, 21), (3, 15), (3, 16), (3, 20), (4, 16), (4, 17), (4, 19), (5, 12), (5, 15), (5, 19), (6, 11), (6, 12), (6, 18), (7, 9), (7, 10), (7, 18), (8, 13), (8, 14), (8, 15), (9, 17), (10, 14), (11, 14), (11, 17), (18, 22), (19, 22), (20, 22), (21, 22)]

G = nx.Graph()
G.add_edges_from(edges)

def get_girth(G):
    girth = float('inf')
    for n in G.nodes():
        # BFS to find shortest cycle
        queue = [(n, [n])]
        visited = {n: [n]}
        while queue:
            curr, path = queue.pop(0)
            for neighbor in G.neighbors(curr):
                if neighbor not in path:
                    new_path = path + [neighbor]
                    visited[neighbor] = new_path
                    queue.append((neighbor, new_path))
                elif len(path) > 2 and neighbor == path[0]:
                    girth = min(girth, len(path))
    return girth

print("Girth:", get_girth(G))

