adj = {i: [] for i in range(23)}
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

degrees = [len(adj[i]) for i in range(23)]
print("Degrees:", degrees)

def get_girth(adj):
    girth = float('inf')
    for start in range(23):
        dist = {start: 0}
        queue = [(start, -1)]
        while queue:
            curr, parent = queue.pop(0)
            for neighbor in adj[curr]:
                if neighbor == parent:
                    continue
                if neighbor in dist:
                    girth = min(girth, dist[curr] + dist[neighbor] + 1)
                else:
                    dist[neighbor] = dist[curr] + 1
                    queue.append((neighbor, curr))
    return girth

print("Girth:", get_girth(adj))
